exec:
console.clear();
logger.struc("==========================================================================================");
logger.struc("===== FirmWareManager_/create-device-group+test.completeness ===================================================");
logger.struc("==========================================================================================");


/****************************************************************************************
* Loading Input Data from File
****************************************************************************************/
var inputFromFile;
try {
    inputFromFile = data

} catch (error) {
    logger.error("! Input data could not be loaded.")
}


/****************************************************************************************
* Setting Environmental Variables 
****************************************************************************************/
try {
    pm.environment.clear();

    let mode;
    mode = inputFromFile.mode;
    // Mode to be applied while running this testcase collection 
    //   "analysis" -> human does detailed analysis of response bodies etc.
    //   "testing" -> automated approval based on binary result
    //   "debugging" -> support for programming the testcase collection

    let logLevel;
    switch(mode) {
        case "debugging":
            logLevel = "debug";
            break;
        case "analysis":
            logLevel = "log";
            break;
        case "testing":
            logLevel = "error";
            break;
        default:
            logLevel = "debug";
    };
    // Level of detail of the logging; find more info in pre-request script on the collection's level

    let serverList = [];
    serverList = inputFromFile.serverList;
    // list of addresses of applications, controllers etc.
    // serverName : key attribute for identifying the servers
    // dummyUri : http address that shall be addressed by bare processing Requests
    // server : part of the URI that is comprised from protocol, IP address and TCP port
    // pathToControlConstruct : part of the URI that is identical for all Requests that are addressing into the device's data tree
    // authorizationCode : authentication that has to be sent in case of BasicAuth protection (e.g. OpenDaylight NBI)
    // operationKey : ApiKey that has to be sent in case of addressing a MW SDN application (e.g. MicroWaveDeviceInventory)
    // userName : user header to be sent in case of addressing a MW SDN application
    // originator : originator header to be sent in case of addressing a MW SDN application
    // xCorrelator : x-correlator header to be sent in case of addressing a MW SDN application
    // traceIndicator : trace-indicator header to be sent in case of addressing a MW SDN application
    // customerJourney : customer-journey header to be sent in case of addressing a MW SDN application

    let collectionInputList = [];
    collectionInputList = inputFromFile.collectionInputList;
    // list of inputs to individual test case collections
    // serverToBeApplied : server that shall be addressed in the respective request/test case
    // linkId : Telefonica LinkID of an example microwave link
    // kindOfReference : 'dynamic' for testing against implementations, 'static' for testing against simulators
    // suffixUrlEncodingIsRequired : e.g. Mockoon requires the suffix being url encoded, but applications vice versa
    //
    // test parameters: note that not all parameters given in the collection are used for this testcase, only those relevant according to requestBody schema    
    // mountName : mountName of the device that is to be validated
    // mountNameList : list of relevant mountNames
    // deviceGroupLabel : label identifying a device group
    // deviceModelName : name of the device model    
    // firmwareResourceName : name of a firmware resource
    // firmwareResourceVersion : version of that firmware resource
    // firmwareStatus : firmware status ('active', 'stand-by', 'not-yet-defined')
    // purgeDate : timestamp indicating when devices are scheduled for purging
    // hardwareExtractionFunction : function used to determine hardware information from a device
    // firmwareExtractionFunction : function used to determine firmware information from a device
    // targetFunction : function executed by the pulser
    // isActivated : indicates whether the function execution is active in the pulser
    // periodLength : execution interval of the pulser in seconds
    // nextTime : next scheduled execution timestamp
    // endingTime : timestamp after which the pulser shall no longer be executed
    // serverLabel : label identifying a server configuration
    // userName : user name used for server access
    // password : password used for server access
    // sshKey : SSH key used for server access
    // sourceUri : path on the server where the firmware file is located
    // fileName : firmware file name
    // esName : name of the Elasticsearch client configuration
    // url : Elasticsearch endpoint URL
    // apiKey : API key used for Elasticsearch access
    // indexAlias : Elasticsearch index alias
    // operationalState : operational state of the Elasticsearch client
    // lifeCycleState : lifecycle state of the Elasticsearch client
    pm.environment.set("mode", mode);
    pm.environment.set("logLevel", logLevel);
    pm.environment.set("serverList", serverList);
    pm.environment.set("collectionInputList", collectionInputList);

} catch (error) {
    logger.error("! Environment variables could not be set.")
}


/****************************************************************************************
* Setting Collection Variables 
****************************************************************************************/
try {
    pm.collectionVariables.clear()

} catch (error) {
    logger.error("! Collection variables could not be set.")
}


/****************************************************************************************
* Setting Local Variables and Preparing the Request
****************************************************************************************/
try {
    let uri;
    let dummyServerInfo;
    dummyServerInfo = ExtractServerInformation(inputFromFile.serverList, "dummy");
    uri = dummyServerInfo.dummyUri;

    pm.variables.clear();

    pm.variables.set("uri", uri);

    pm.request.headers.upsert({ key: "Accept", value: "application/json" });
    pm.request.headers.upsert({ key: "Content-Type", value: "application/json" })

} catch (error) {
    logger.error("! Local variables could not be set.")
}


/****************************************************************************************
* Functions
****************************************************************************************/
function ExtractServerInformation(serverList, searchedServerName) {
    try {
        for(let i=0; i<serverList.length; i++) {
            if(serverList[i].serverName==searchedServerName) {
                return serverList[i]
            }
        }
    } catch (error) {
        logger.error("! serverList not found or faulty");
        return {}
    }
    logger.warn("Server could not be found in serverList.");
    return {}
}
